// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the calldata bytes so the fuzzer can explore many inputs; address of callee is fixed by deploying Reverter
    function testFuzz_property(bytes memory calldat) public {
        // deploy an adversarial callee that always reverts on fallback/receive
        Reverter r = new Reverter();

        // ensure calldata is some arbitrary payload; no restriction needed
        // Call c.forward with the reverter's address and the fuzzed calldata.
        bool ok;
        try c.forward(address(r), calldat) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: when the callee reverts, reference implementation propagates and thus forward MUST revert (ok == false)
        // The mutant removed the require, so for some calldat it will return ok == true; we assert the correct behavior (must revert)
        assertTrue(!ok);
    }
}

contract Reverter {
    // Always revert on any call (fallback and receive)
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
